-- etl-craft: convert-task-targets
ALTER TABLE CFG_TASKS ADD COLUMN TARGET_TABLE_ID BIGINT REFERENCES CFG_TABLES(TABLE_ID);
ALTER TABLE CFG_TASKS ADD COLUMN TARGET_ACTIVE_FLAG VARCHAR(1) NOT NULL DEFAULT 'Y' CONSTRAINT ck_tasks_target_active CHECK (TARGET_ACTIVE_FLAG IN ('Y','N'));
ALTER TABLE AUD_CFG_TASKS_HISTORY ADD COLUMN TARGET_TABLE_ID BIGINT;
ALTER TABLE AUD_CFG_TASKS_HISTORY ADD COLUMN TARGET_ACTIVE_FLAG VARCHAR(1);
ALTER TABLE CFG_TASK_PARAMETERS ADD CONSTRAINT ck_taskparameters_target CHECK (upper(trim(PARAMETER_NAME)) <> 'TARGET_OBJECT');
CREATE INDEX ix_tasks_target ON CFG_TASKS (TARGET_TABLE_ID) WHERE TARGET_TABLE_ID IS NOT NULL;
COMMENT ON TABLE CFG_TASK_PARAMETERS IS 'A task''s settings as name and value pairs (SQL_ACTION, SOURCE_SQL, ...); TARGET_OBJECT is derived from the task table reference. Which names each handler reads is documented in the task parameter reference.';
